1	/**
2	 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { assertCan } from "@/lib/permissions";
8	import { assertValidSlug, uniqueSlug } from "@/lib/slug";
9	import { assertOrgScope } from "@/lib/tenant";
10	import * as memberRepo from "@/server/repositories/member-repository";
11	import * as orgRepo from "@/server/repositories/organization-repository";
12	import * as projectRepo from "@/server/repositories/project-repository";
13	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
14	import * as usageRepo from "@/server/repositories/usage-repository";
15	import { record } from "./activity-service";
16	import { envelope, orgResource, requireFound } from "./_support";
17	import type {
18	  CreateOrganizationInput,
19	  DeleteOrganizationInput,
20	  UpdateOrganizationInput,
21	} from "@/schemas/organization";
22	import type { OrgId, UserId } from "@/types/common";
23	import type { Actor } from "@/types/member";
24	import type { Organization, OrganizationSummary } from "@/types/organization";
25	
26	/**
27	 * Creates an organization and everything it cannot exist without: the owner's
28	 * membership row and a subscription. Sign-up and "create another workspace"
29	 * both land here, which is why it takes a bare `ownerId` rather than an
30	 * `Actor` — there is no membership to build one from yet.
31	 */
32	export async function createOrganization(
33	  ownerId: UserId,
34	  input: CreateOrganizationInput,
35	): Promise<Organization> {
36	  assertValidSlug(input.slug);
37	
38	  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
39	  const slug = uniqueSlug(input.slug, taken);
40	
41	  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);
42	
43	  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
44	  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
45	  await usageRepo.recomputeUsage(org.id);
46	
47	  await emit("member.joined", {
48	    ...envelope(org.id, ownerId),
49	    memberId: owner.id,
50	    userId: ownerId,
51	    role: owner.role,
52	  });
53	
